composeOverride:
# Generated by McHarbor App Store
services:
  {{serviceName}}:
    image: {{image}}
    container_name: {{containerName}}
    restart: unless-stopped
{{ports}}
    environment:
      TZ: {{env.TZ}}
      LISTMONK_DB__HOST: {{serviceName}}-db
      LISTMONK_DB__PORT: {{env.LISTMONK_DB__PORT}}
      LISTMONK_DB__USER: {{env.LISTMONK_DB__USER}}
      LISTMONK_DB__PASSWORD: {{env.LISTMONK_DB__PASSWORD}}
      LISTMONK_DB__DATABASE: {{env.LISTMONK_DB__DATABASE}}
      LISTMONK_ADMIN_USER: {{env.LISTMONK_ADMIN_USER}}
      LISTMONK_ADMIN_PASSWORD: {{env.LISTMONK_ADMIN_PASSWORD}}
    volumes:
      - {{appDataPath}}/config:/etc/listmonk
    depends_on:
      - {{serviceName}}-db
  {{serviceName}}-db:
    image: postgres:16-alpine
    container_name: {{serviceName}}-db
    restart: unless-stopped
    environment:
      POSTGRES_USER: {{env.LISTMONK_DB__USER}}
      POSTGRES_PASSWORD: {{env.LISTMONK_DB__PASSWORD}}
      POSTGRES_DB: {{env.LISTMONK_DB__DATABASE}}
    volumes:
      - {{appDataPath}}/db:/var/lib/postgresql/data
